<template>
  <aside class="assistant">
    <div class="head"><div><small>INQUIRY STUDIO</small><h2>教学助手</h2></div><button class="mobile" @click="$emit('close')">返回教案</button></div>
    <div class="context"><strong>参考资料</strong><button @click="$emit('sources')">{{ sourceCount ? `已选择 ${sourceCount} 项 · 调整` : '未选择 · 选择资料' }}</button><p v-if="sourceCount">所选资料的检索尚未接入，请清除并保存后使用通用分析。</p><p v-else>未使用参考资料，结果为通用模型建议，请教师核实。</p></div>
    <div class="conversation" aria-live="polite"><div class="bubble intro">可以让我分析整份教案，或先在正文中选中一段，再告诉我如何优化。</div><div v-if="selectedText" class="selection"><strong>已选中正文</strong><p>{{ selectedText }}</p></div><template v-if="response"><div class="bubble"><strong>分析建议</strong><p>{{ response.analysis }}</p></div><div v-if="response.suggestion" class="proposal"><strong>建议修改</strong><p>{{ response.suggestion }}</p><button v-if="response.selection" :disabled="dirty || stale || locked" @click="$emit('apply', response.suggestion, response.selection)">采纳到所选位置</button><small v-if="locked">教案已锁定，不能采纳修改。</small><small v-if="stale">正文或选择已变化，请重新生成建议。</small></div></template><p v-if="error" class="error" role="alert">{{ error }}</p></div>
    <div class="composer"><textarea v-model="instruction" rows="3" placeholder="输入问题或修改要求，例如：让选中段落更适合四年级学生" aria-label="向教学助手提问"></textarea><div><button :disabled="loading || dirty || sourceCount > 0" @click="run('分析整份教案')">{{ loading ? '正在分析…' : '分析教案' }}</button><button class="primary" :disabled="loading || dirty || sourceCount > 0 || !instruction.trim()" @click="run(instruction)">发送</button></div><small v-if="dirty">请先保存修改，再进行分析。</small><small v-else>模型可能出错，采纳前请核实。</small></div>
  </aside>
</template>
<script setup lang="ts">
import {computed, ref, watch} from 'vue';
import {json, request} from './api';
const props = defineProps<{workspaceId:string; artifactId:string; version:number; dirty:boolean; locked:boolean; sourceCount:number; selectedText:string; selectionKey:string}>();
defineEmits<{close:[]; sources:[]; apply:[text:string, selection:string]}>();
const instruction = ref(''), loading = ref(false), error = ref('');
const response = ref<{analysis:string; suggestion:string; selection:string; selectionKey:string; version:number} | null>(null);
const stale = computed(() => !!response.value && (response.value.selectionKey !== props.selectionKey || response.value.version !== props.version));
watch(() => props.sourceCount, () => { response.value = null; });
async function run(command:string) { if (loading.value || props.dirty || props.sourceCount) return; loading.value = true; error.value = ''; const selection = command === '分析整份教案' ? '' : props.selectedText; const key = props.selectionKey; const version = props.version; try { const result = await request<{analysis:string;suggestion:string}>(`/api/inquiry-workspaces/${encodeURIComponent(props.workspaceId)}/lesson-document/${encodeURIComponent(props.artifactId)}/assistant`, json('POST', {expected_version:version,instruction:command,selected_text:selection})); response.value = {...result,selection,selectionKey:key,version}; } catch(e) { error.value = e instanceof Error ? e.message : '分析失败，请重试。'; } finally { loading.value = false; } }
</script>
<style scoped>
.assistant{background:#fff;border:1px solid #d5e4dc;border-radius:12px;position:sticky;top:86px;height:calc(100vh - 106px);min-height:400px;display:flex;flex-direction:column;overflow:hidden}.head,.context,.composer{padding:16px;border-bottom:1px solid #e8f0eb}.head{display:flex;justify-content:space-between}.head h2{font-size:18px;margin:2px 0}.head small,.composer small{color:#70877c}.context p,.selection p,.proposal p,.bubble p{white-space:pre-wrap;overflow-wrap:anywhere}.context p{font-size:12px;color:#70877c}.context button{margin-left:8px}.conversation{flex:1;overflow:auto;padding:16px}.bubble,.selection,.proposal{background:#f5f8f6;padding:12px;border-radius:10px;margin-bottom:12px;font-size:13px}.selection{border-left:3px solid #27816c}.proposal{background:#edf7f1}.proposal small{display:block;color:#a34939}.error{color:#a34939}.composer{border:0;border-top:1px solid #e8f0eb}.composer textarea{width:100%;resize:vertical;padding:10px;border:1px solid #d5e4dc;border-radius:8px;font:inherit}.composer>div{display:flex;justify-content:space-between;gap:8px;margin:8px 0}.assistant button{font:inherit;background:white;border:1px solid #d5e4dc;color:#183a33;border-radius:8px;padding:7px 10px;cursor:pointer}.assistant button:disabled{opacity:.5;cursor:not-allowed}.assistant .primary{background:#27816c;color:white}.mobile{display:none}@media(max-width:700px){.assistant{position:static;height:auto;min-height:65vh}.mobile{display:block}}
</style>
